package lk.repairdesk.api.service; import lk.repairdesk.api.domain.*; import lk.repairdesk.api.dto.WorkDtos.*; import lk.repairdesk.api.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient; import java.util.*; @Service public class WorkService {private final RepairService repairs;private final DiagnosisRepository diagnoses;private final QuotationRepository quotes;private final CurrentUserService current;private final RestClient client;public WorkService(RepairService r,DiagnosisRepository d,QuotationRepository q,CurrentUserService c,RestClient.Builder b,@Value("${app.decision-service-url}")String url){repairs=r;diagnoses=d;quotes=q;current=c;client=b.baseUrl(url).build();} @Transactional public Diagnosis diagnose(Long id,DiagnosisRequest x){var rr=repairs.get(id);var d=diagnoses.findByRepairRequestId(id).orElseGet(Diagnosis::new);d.setRepairRequest(rr);d.setTechnician(current.get());d.setSummary(x.summary().trim());d.setRepairable(x.repairable());d.setEstimatedSuccessRate(x.estimatedSuccessRate());rr.setStatus(RepairStatus.QUOTED);return diagnoses.save(d);} @Transactional public Quotation quote(Long id,QuotationRequest x){var q=new Quotation();q.setRepairRequest(repairs.get(id));q.setLabourCost(x.labourCost());q.setPartsCost(x.partsCost());q.setTax(x.tax());q.setValidUntil(x.validUntil());q.setNotes(x.notes());return quotes.save(q);} public List<Quotation> quotations(Long id){repairs.get(id);return quotes.findByRepairRequestIdOrderByCreatedAtDesc(id);} public Map recommendation(RecommendationRequest x){return client.post().uri("/recommend").contentType(MediaType.APPLICATION_JSON).body(x).retrieve().body(Map.class);} }